// HasVotesWith applies the HasEdge predicate on the "votes" edge with a given conditions (other predicates).
func HasVotesWith(preds ...predicate.ProviderCommentVote) predicate.ProviderComment {
	return predicate.ProviderComment(func(s *sql.Selector) {
		step := newVotesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProviderComment) predicate.ProviderComment {
	return predicate.ProviderComment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProviderComment) predicate.ProviderComment {
	return predicate.ProviderComment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProviderComment) predicate.ProviderComment {
	return predicate.ProviderComment(sql.NotPredicates(p))
}
